static int source_starts_void_cast_now (const char *p) {

    if (!p) {
        return 0;
    }
    
    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') {
        p++;
    }
    
    if (*p++ != '(') {
        return 0;
    }
    
    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') {
        p++;
    }
    
    if (p[0] != 'v' || p[1] != 'o' || p[2] != 'i' || p[3] != 'd') {
        return 0;
    }
    
    p += 4;
    
    if ((*p >= 'A' && *p <= 'Z') || (*p >= 'a' && *p <= 'z') || (*p >= '0' && *p <= '9') || *p == '_') {
        return 0;
    }
    
    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') {
        p++;
    }
    
    return *p == ')';

}

